wc=r'''async function loadWorkCenter(){if(!canPage('workcenter'))return;if(workcenterScope==='team'&&!['CFO','Supervisor'].includes(profile?.role))workcenterScope='mine';populateWorkCenterEmployeeFilter();document.querySelectorAll('[data-wctab]').forEach(b=>b.classList.toggle('active',b.dataset.wctab===workcenterTab));document.getElementById('wcMineBtn')?.classList.toggle('active',workcenterScope==='mine');document.getElementById('wcTeamBtn')?.classList.toggle('active',workcenterScope==='team');document.getElementById('wcScopeWrap')?.classList.toggle('hidden',!['CFO','Supervisor'].includes(profile?.role));const req=[sb.rpc('get_workcenter_items_v4',{p_tab:workcenterTab,p_scope:workcenterScope,p_filters:workCenterFilters()}),sb.rpc('get_workcenter_summary_v4',{p_scope:workcenterScope})];if(['CFO','Supervisor'].includes(profile?.role))req.push(sb.rpc('get_team_operations_monitor_v4'));const out=await Promise.all(req);if(out[0].error){console.error('WorkCenter V4 items',out[0].error);workcenterItems=[]}else workcenterItems=out[0].data||[];workcenterSummary=out[1].error?{}:(out[1].data||{});teamOperationsMonitor=out[2]?.error?[]:(out[2]?.data||[]);renderWorkCenter();renderTeamOperationsMonitor()}
function renderWorkCenter(){const body=document.getElementById('workcenterBody'),summary=document.getElementById('workcenterSummary');if(!body||!summary)return;const c=workcenterSummary||{};document.getElementById('wcCountActive').textContent=c.active?`(${latinDigits(c.active)})`:'';document.getElementById('wcCountWaitingMe').textContent=c.waiting_on_me?`(${latinDigits(c.waiting_on_me)})`:'';document.getElementById('wcCountWaitingOthers').textContent=c.waiting_others?`(${latinDigits(c.waiting_others)})`:'';document.getElementById('wcCountExceptions').textContent=c.exceptions?`(${latinDigits(c.exceptions)})`:'';document.getElementById('wcCountCompleted').textContent=c.completed_today?`(${latinDigits(c.completed_today)})`:'';summary.innerHTML=`<div class="card workcenter-summary-card"><span class="muted">${displayText('عملي الآن')}</span><b>${latinDigits(c.active||0)}</b></div><div class="card workcenter-summary-card"><span class="muted">${displayText('بانتظار مني')}</span><b>${latinDigits(c.waiting_on_me||0)}</b></div><div class="card workcenter-summary-card"><span class="muted">${displayText('بانتظار الآخرين')}</span><b>${latinDigits(c.waiting_others||0)}</b></div><div class="card workcenter-summary-card"><span class="muted">${displayText('الاستثناءات')}</span><b>${latinDigits(c.exceptions||0)}</b></div><div class="card workcenter-summary-card"><span class="muted">${displayText('مكتمل اليوم')}</span><b>${latinDigits(c.completed_today||0)}</b></div>`;body.innerHTML=(workcenterItems||[]).map(w=>{const acts=Array.isArray(w.available_actions)?w.available_actions:[];const actionHtml=acts.slice(0,6).map(a=>`<button class="btn ${['START','COMPLETE','APPROVE_COMPLETION','EXECUTE_PAYMENT','REGISTER_ACCOUNTING','FINALIZE_POSTING'].includes(a.action)?'workcenter-action-primary':''}" onclick="openWorkCenterAction('${esc(w.work_item_id)}','${esc(a.action)}')">${esc(workCenterActionLabel(a.action))}</button>`).join('');const rem=Number(w.remaining_minutes),remCls=Number.isFinite(rem)&&rem<0?'time-negative':'time-positive';return `<tr class="${w.is_overdue?'workcenter-row-overdue':''}"><td class="workcenter-title"><b>${esc(w.title)}</b><div class="workflow-source">${esc(workflowSourceLabel(w.source_type))}${w.task_source_type?` · ${esc(w.task_source_type)}`:''}</div></td><td>${esc(displayText(workflowTypeLabel(w.item_type)))}</td><td>${esc(w.assignee_name||'—')}</td><td>${esc(w.reviewer_name||'—')}</td><td>${workflowStatusBadge(w.status)}</td><td>${w.assigned_at?fmt(w.assigned_at):'—'}</td><td class="wc-time-cell">${minutesLabel(w.planned_minutes)}</td><td>${workflowDueHtml(w.due_at,w.status)}</td><td class="wc-time-cell ${remCls}">${minutesLabel(w.remaining_minutes)}</td><td>${w.quality_score===null||w.quality_score===undefined?'—':`<span class="quality-score">${Number(w.quality_score).toFixed(1)}%</span>`}</td><td><div class="workcenter-actions">${actionHtml||`<span class="muted">${currentLang==='en'?'No action required':'لا يوجد إجراء مطلوب'}</span>`}${workCenterDetailsButton(w)}<button class="btn" onclick="openWorkflowTimeline('${esc(w.source_type)}','${esc(w.source_id)}','${esc(w.title)}')">${displayText('عرض المسار')}</button></div></td></tr>`}).join('')||`<tr><td colspan="11"><div class="workflow-empty">${displayText('لا توجد عناصر عمل في هذا العرض.')}</div></td></tr>`;applyLanguage(document.getElementById('workcenter'))}
'''
