if start<0 or end<0: raise SystemExit('legacy complete/review block missing')
legacy=r'''async function completeTask(id){const result=prompt(currentLang==='en'?'Describe what you completed or concluded:':'اكتب وصف ما تم إنجازه أو النتيجة التي توصلت إليها:');if(!result||!result.trim())return;const t=tasks.find(x=>x.id===id);if(t?.blocker_note)return alert(currentLang==='en'?'Clear the blocker before submitting for review.':'يجب إزالة التعثر قبل إرسال المهمة للمراجعة.');let justification='';if(t&&taskJustificationRequired(t)){justification=prompt(currentLang==='en'?'Delay justification is required:':'التبرير إلزامي قبل إرسال المهمة للمراجعة:')||'';if(!justification.trim())return}const {error}=await sb.rpc('submit_finance_task_result',{p_task_id:id,p_result_description:result.trim(),p_justification:justification.trim()||null});if(error)return alert(error.message);await reloadAll();await loadWorkCenter();alert(currentLang==='en'?'Task submitted for review.':'تم إرسال المهمة للمراجعة.')}
async function reviewTask(id,approve){let score=null;if(approve){const raw=prompt(currentLang==='en'?'Result quality score from 0 to 100:':'تقييم نتيجة المهمة من 0 إلى 100:');if(raw===null)return;score=Number(raw);if(!Number.isFinite(score)||score<0||score>100)return alert(currentLang==='en'?'Invalid score.':'التقييم غير صحيح.')}const note=prompt(approve?(currentLang==='en'?'Review note (optional):':'ملاحظة المراجعة (اختياري):'):(currentLang==='en'?'Reason for returning the task:':'سبب إعادة المهمة للعمل:'))||'';if(!approve&&!note.trim())return alert(currentLang==='en'?'Rework reason is required.':'سبب إعادة المهمة للعمل إلزامي.');const {error}=await sb.rpc('review_finance_task_scored',{p_task_id:id,p_approve:approve,p_quality_score:score,p_note:note||null});if(error)return alert(error.message);await reloadAll();await loadWorkCenter()}
'''
s=s[:start]+legacy+s[end:]

# Employee performance history/report functions inserted before KPI report state.
marker='let kpiReportRows=[];'
if marker not in s: raise SystemExit('KPI marker missing')
report=r'''function currentMonthRange(){const d=new Date(),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),last=new Date(y,d.getMonth()+1,0).getDate();return [`${y}-${m}-01`,`${y}-${m}-${String(last).padStart(2,'0')}`]}
function openEmployeePerformanceReport(userId=''){if(!['CFO','Supervisor'].includes(profile.role)&&userId!==profile.id)return;const [f,t]=currentMonthRange();const opts=(profiles||[]).filter(x=>['Supervisor','BankAccountant','GLAccountant','ARAccountant','APAccountant'].includes(x.role)).map(x=>`<option value="${esc(x.id)}" ${x.id===(userId||profile.id)?'selected':''}>${esc(x.full_name)}</option>`).join('');showModal(currentLang==='en'?'Employee performance history':'سجل وتقارير أداء الموظف',`<div class="modal-grid"><div><label>${displayText('الموظف')}</label><select id="perfEmp">${opts}</select></div>${input('perfFrom',displayText('من'),f,'date')}${input('perfTo',displayText('إلى'),t,'date')}</div><div class="report-toolbar" style="margin-top:12px"><button class="btn primary" onclick="loadEmployeePerformanceReport()">${currentLang==='en'?'Load':'عرض'}</button><button class="btn" onclick="setPerformanceYtd()">YTD</button><button class="btn" onclick="printEmployeePerformanceReport()">${displayText('طباعة / PDF')}</button></div><div id="employeePerformanceOutput"></div>`);loadEmployeePerformanceReport()}
function setPerformanceYtd(){const d=new Date(),y=d.getFullYear();document.getElementById('perfFrom').value=`${y}-01-01`;document.getElementById('perfTo').value=riyadhToday();loadEmployeePerformanceReport()}
async function loadEmployeePerformanceReport(){const uid=val('perfEmp'),from=val('perfFrom'),to=val('perfTo'),out=document.getElementById('employeePerformanceOutput');if(!uid||!out)return;out.innerHTML='<div class="muted">...</div>';const {data,error}=await sb.rpc('get_employee_performance_report_v4',{p_user_id:uid,p_from:from||null,p_to:to||null});if(error){out.innerHTML=`<div class="warning-box">${esc(error.message)}</div>`;return}employeePerformanceReport=data||{};const e=data.employee||{},sm=data.summary||{},items=data.items||[];out.innerHTML=`<div class="mini-kpis"><div class="card"><span class="muted">${currentLang==='en'?'Completed':'منجز'}</span><b>${latinDigits(sm.completed||0)}</b></div><div class="card"><span class="muted">${currentLang==='en'?'On-time rate':'في الموعد'}</span><b>${Number(sm.on_time_rate||0).toFixed(1)}%</b></div><div class="card"><span class="muted">${currentLang==='en'?'Average quality':'متوسط تقييم النتيجة'}</span><b>${Number(sm.avg_quality_score||0).toFixed(1)}%</b></div><div class="card"><span class="muted">${currentLang==='en'?'Transactions':'إجراءات تشغيلية'}</span><b>${latinDigits(sm.transaction_items||0)}</b></div></div><div class="note">${esc(e.full_name||'')} — ${esc(displayText(ROLE_LABEL[e.role]||e.role||''))} | ${esc(data.from||'')} → ${esc(data.to||'')}<br>${currentLang==='en'?'Historical records are retained permanently; printing does not delete them.':'السجل التاريخي محفوظ ولا يتم حذف البيانات بعد الطباعة.'}</div><div class="table-wrap" style="margin-top:10px"><table class="performance-report-table"><thead><tr><th>${displayText('التاريخ')}</th><th>${displayText('المهمة')}</th><th>${displayText('النوع')}</th><th>${currentLang==='en'?'Assigned':'الإسناد'}</th><th>${currentLang==='en'?'Started':'البدء'}</th><th>${currentLang==='en'?'Completed':'الإنهاء'}</th><th>${currentLang==='en'?'On time':'الموعد'}</th><th>${currentLang==='en'?'Quality':'التقييم'}</th><th>${currentLang==='en'?'Result':'النتيجة'}</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.date||'')}</td><td>${esc(i.title||'')}</td><td>${esc(displayText(workflowTypeLabel(i.item_type)||i.item_type||''))}</td><td>${i.assigned_at?fmt(i.assigned_at):'—'}</td><td>${i.started_at?fmt(i.started_at):'—'}</td><td>${i.completed_at?fmt(i.completed_at):'—'}</td><td>${i.on_time===null?'—':(i.on_time?`<span class="badge green">${currentLang==='en'?'On time':'في الموعد'}</span>`:`<span class="badge red">${currentLang==='en'?'Late':'متأخر'}</span>`)}</td><td>${i.quality_score===null?'—':`${Number(i.quality_score).toFixed(1)}%`}</td><td class="performance-report-result">${esc(i.result_description||'—')}</td></tr>`).join('')||`<tr><td colspan="9" class="muted">—</td></tr>`}</tbody></table></div>`}
function printEmployeePerformanceReport(){if(!employeePerformanceReport?.employee)return alert(currentLang==='en'?'Load a report first.':'اعرض التقرير أولًا.');const out=document.getElementById('employeePerformanceOutput');const w=window.open('','_blank');if(!w)return;w.document.write(`<html dir="${currentLang==='en'?'ltr':'rtl'}"><head><meta charset="utf-8"><title>${esc(employeePerformanceReport.employee.full_name||'')}</title><style>body{font-family:Arial,Tahoma;padding:24px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccc;padding:7px;text-align:right}.card{display:inline-block;border:1px solid #ccc;padding:10px;margin:5px}.muted{color:#666}.note{padding:10px;border:1px solid #ddd;margin:10px 0}</style></head><body><h2>${currentLang==='en'?'Employee Performance Report':'تقرير أداء الموظف'}</h2>${out.innerHTML}</body></html>`);w.document.close();w.focus();w.print()}
'''
s=s.replace(marker,report+marker,1)

# After reloadAll render, keep active Work Center synchronized.
s=s.replace(' renderAll()\n}', " renderAll()\n if(document.getElementById('workcenter')?.classList.contains('active')){try{await loadWorkCenter()}catch(e){console.error('WorkCenter refresh failed',e)}}\n}",1)

p.write_text(s,encoding='utf-8')
